namespace ghidra.app.plugin.assembler.sleigh.expr;




using ghidra.app.plugin.assembler.sleigh.sem;
using ghidra.app.plugin.processors.sleigh.expression;

/**
 * Solves expressions of a context register field
 * 
 * <p>
 * Essentially, this just encodes the goal into the field, if it can be represented in the given
 * space and format. Otherwise, there is no solution.
 */
public class ContextFieldSolver : AbstractExpressionSolver<ContextField> {

	public ContextFieldSolver() : base(typeof(ContextField))
    {
	}

	/* @Override */
	public AssemblyResolution solve(AbstractAssemblyResolutionFactory<object,object> factory,
			ContextField cf, MaskedLong goal, Map<string, Long> vals, AssemblyResolvedPatterns cur,
			Set<SolverHint> hints, string description) {
		System.Diagnostics.Debug.Assert(cf.minValue() == 0); // In case someone decides to do signedness there.
		if (!goal.isInRange(cf.maxValue(), cf.hasSignbit())) {
			return factory.newErrorBuilder()
					.error("Value " + goal + " is not valid for " + cf)
					.description(description)
					.build();
		}
		AssemblyPatternBlock block = AssemblyPatternBlock.fromContextField(cf, goal);
		return factory.contextOnly(block, description);
	}

	/* @Override */
	public MaskedLong getValue(ContextField cf, Map<string, Long> vals,
			AssemblyResolvedPatterns cur) {
		if (cur == null) {
			return null;
		}
		return valueForResolution(cf, vals, cur);
	}

	/* @Override */
	public int getInstructionLength(ContextField cf) {
		return 0; // this is a context field, not an instruction (token) field
	}

	/* @Override */
	public MaskedLong valueForResolution(ContextField cf, Map<string, Long> vals,
			AssemblyResolvedPatterns rc) {
		int size = cf.getByteEnd() - cf.getByteStart() + 1;
		MaskedLong res = rc.readContext(cf.getByteStart(), size);
		res = res.shiftRight(cf.getShift());
		if (cf.hasSignbit()) {
			res = res.signExtend(cf.getEndBit() - cf.getStartBit() + 1);
		}
		else {
			res = res.zeroExtend(cf.getEndBit() - cf.getStartBit() + 1);
		}
		return res;
	}
}
